export const WEBAUTHN_CHALLENGE_TTL_MS = 5 * 60_000
export const OAUTH_STATE_TTL_MS = 10 * 60_000

/** What a stored WebAuthn challenge may be used for — a challenge from one ceremony must never complete another. */
export type WebAuthnPurpose = 'register' | 'login' | 'step_up'

export interface WebAuthnChallenge {
  id: string
  /** base64url, as generated by the WebAuthn library. */
  challenge: string
  purpose: WebAuthnPurpose
  /** The user the ceremony is for; null for a usernameless sign-in. */
  userId: string | null
  createdAt: Date
  expiresAt: Date
}

export type OAuthPurpose = 'login' | 'link'

/** One in-flight OAuth authorization: survives the browser round trip to the provider and back. */
export interface OAuthState {
  id: string
  /** Hash of the `state` value sent to the provider; the raw value only ever lives in the redirect. */
  stateHash: string
  provider: string
  codeVerifier: string
  purpose: OAuthPurpose
  /** Set for `link`: the signed-in user who started it, and the only one allowed to finish it. */
  userId: string | null
  createdAt: Date
  expiresAt: Date
}
